  ('audit_1_2', 'D', 48, 'Apakah owner paham bahwa PPN baru wajib dipungut bila sudah jadi PKP (omzet >Rp4,8 M)?', 'Di bawah ambang itu JANGAN memungut PPN. Dasar: UU HPP.', false, false, NULL, false, true, 1.00, 48),
  ('audit_1_2', 'D', 49, 'Apakah perizinan dasar (NIB melalui OSS) sudah ada?', 'Dasar: PP 5/2021 (OSS-RBA). NIB gratis, fondasi legalitas.', false, false, NULL, false, true, 1.00, 49),
