  ('audit_3_4', 'D', 29, 'Seluruh pekerja terdaftar BPJS Ketenagakerjaan (5 program) & Kesehatan, iuran disetor benar?', 'Dasar: UU 24/2011; Perpres 64/2020; PP 6/2025 (JKP).', false, false, NULL, false, false, 1.00, 29),
  ('audit_3_4', 'D', 30, 'K3 / SMK3 diterapkan sesuai skala usaha?', 'Dasar: PP 50/2012.', false, false, NULL, false, false, 1.00, 30),
  ('audit_3_4', 'D', 31, 'Perlindungan data pribadi pelanggan & karyawan sesuai UU PDP?', 'Dasar: UU 27/2022 (PDP) — makin ditegakkan; relevan untuk ritel berbasis data.', false, false, NULL, false, false, 1.00, 31),
  ('audit_3_4', 'D', 32, 'Bila berizin via OSS: LKPM & kewajiban perizinan berkelanjutan dipenuhi?', 'Dasar: PP 5/2021 (OSS-RBA) — konfirmasi kewajiban sesuai KBLI.', false, true, 'Bila berizin via OSS', true, false, 1.00, 32),
  ('audit_3_4', 'E', 33, 'Apakah ada jalur succession/kaderisasi untuk SEMUA posisi kunci (min. 1 calon siap per posisi)?', 'Inti masuk fase Talent Building.', true, false, NULL, false, false, 1.00, 33),
  ('audit_3_4', 'E', 34, 'Apakah ada sistem KPI/penilaian kinerja objektif & rutin yang dipakai untuk keputusan?', NULL, true, false, NULL, false, false, 1.00, 34),
  ('audit_3_4', 'E', 35, 'Apakah rekrutmen berbasis kompetensi & nilai, dengan talent pool/pipeline?', NULL, false, false, NULL, false, false, 1.00, 35),
  ('audit_3_4', 'E', 36, 'Apakah ada program pengembangan/pelatihan terstruktur & ber-anggaran (learning path)?', NULL, false, false, NULL, false, false, 1.00, 36),
  ('audit_3_4', 'E', 37, 'Apakah struktur kompensasi & benefit tertata (rank & salary, insentif berbasis kinerja)?', NULL, false, false, NULL, false, false, 1.00, 37),
  ('audit_3_4', 'E', 38, 'Apakah engagement & turnover talent kunci dipantau & dikelola?', NULL, false, false, NULL, false, false, 1.00, 38),
  ('audit_3_4', 'E', 39, 'Apakah human capital dikelola sebagai fungsi strategis (ada HRD/PIC yang mumpuni)?', NULL, false, false, NULL, false, false, 1.00, 39),
  ('audit_3_4', 'F', 40, 'Apakah ada koordinasi lintas-unit + data terintegrasi sehingga owner punya visibilitas TANPA mikro-manajemen?', 'Solusi krisis kontrol = koordinasi, bukan sentralisasi ulang.', true, false, NULL, false, false, 1.00, 40),
  ('audit_3_4', 'F', 41, 'Apakah audit internal independen berjalan & temuannya ditindaklanjuti?', NULL, true, false, NULL, false, false, 1.00, 41),
  ('audit_3_4', 'F', 42, 'Apakah matriks otoritas/wewenang & batas keputusan tiap level tertulis & dipatuhi?', NULL, true, false, NULL, false, false, 1.00, 42),
  ('audit_3_4', 'F', 43, 'Apakah keputusan strategis berbasis data dashboard, bukan firasat/otoritas personal?', NULL, false, false, NULL, false, false, 1.00, 43),
  ('audit_3_4', 'F', 44, 'Apakah blueprint/strategi diturunkan ke OKR/KPI unit & dievaluasi berkala?', 'Pilar "Blueprint" & "Execution Dashboard & Control".', false, false, NULL, false, false, 1.00, 44),
  ('audit_3_4', 'F', 45, 'Apakah ada manajemen risiko & kepatuhan (risk register, conflict of interest, anti-fraud)?', NULL, false, false, NULL, false, false, 1.00, 45),
  ('audit_3_4', 'F', 46, 'Apakah ada deteksi dini terhadap konflik kepentingan/penyimpangan "orang dekat"?', 'Fase keberhasilan memunculkan hasad & "partner pengkhianat" — waspada (materi Sirah Anda).', false, false, NULL, false, false, 1.00, 46),
  ('audit_3_4', 'F', 47, 'Apakah ada forum tata kelola (komisaris/dewan penasihat) yang benar-benar berfungsi?', NULL, false, false, NULL, false, false, 1.00, 47),
  ('audit_3_4', 'G', 48, 'Apakah sistem inti (penjualan, persediaan, keuangan, SDM) terintegrasi dalam satu sistem (ERP/aplikasi)?', NULL, true, false, NULL, false, false, 1.00, 48),
  ('audit_3_4', 'G', 49, 'Apakah ada "satu sumber kebenaran" data lintas bagian?', NULL, false, false, NULL, false, false, 1.00, 49),
  ('audit_3_4', 'G', 50, 'Apakah ada dashboard manajemen yang dipakai untuk keputusan harian/mingguan?', NULL, false, false, NULL, false, false, 1.00, 50),
  ('audit_3_4', 'G', 51, 'Apakah ada kebijakan keamanan, hak akses, & backup data (termasuk kepatuhan UU PDP)?', NULL, false, false, NULL, false, false, 1.00, 51),
  ('audit_3_4', 'H', 52, 'Apakah owner sudah sepenuhnya lepas operasional & fokus pada strategi + pengembangan orang?', NULL, true, false, NULL, false, false, 1.00, 52),
  ('audit_3_4', 'H', 53, 'Apakah owner aktif men-coaching & menumbuhkan middle/senior management?', NULL, false, false, NULL, false, false, 1.00, 53),
  ('audit_3_4', 'H', 54, 'Apakah ada lapisan kepemimpinan yang nyata — bukan satu orang penentu segalanya?', NULL, false, false, NULL, false, false, 1.00, 54),
  ('audit_3_4', 'H', 55, 'Apakah ada rencana suksesi untuk peran OWNER sendiri (kelangsungan kepemimpinan)?', 'Estafet kepemimpinan — materi Sirah Anda; jarang dipikirkan owner yang masih kuat.', true, false, NULL, false, false, 1.00, 55),
  ('audit_3_4', 'H', 56, 'Apakah keputusan tetap tegas namun lewat sistem & nilai, bukan otoritas personal?', NULL, false, false, NULL, false, false, 1.00, 56),
  ('audit_3_4', 'I', 57, 'Apakah inovasi terlembaga (proses & anggaran), bukan tergantung ide owner?', NULL, false, false, NULL, false, false, 1.00, 57),
  ('audit_3_4', 'I', 58, 'Apakah efisiensi biaya & Total Quality Management menjadi budaya yang terukur?', NULL, false, false, NULL, false, false, 1.00, 58),
  ('audit_3_4', 'I', 59, 'Apakah perusahaan memindai tren/teknologi & meremajakan model bisnis secara berkala?', NULL, false, false, NULL, false, false, 1.00, 59),
  ('audit_3_4', 'J', 60, 'Apakah pertumbuhan TIDAK menggerus akhlak, ibadah & integritas owner/tim?', 'Indikator scaling-up berhasil (materi Anda): makin besar makin baik & zuhud, bukan makin sombong.', true, false, NULL, false, false, 1.00, 60),
  ('audit_3_4', 'J', 61, 'Apakah muamalah/akad & instrumen modal dipastikan syariah oleh pihak kompeten (dewan/penasihat syariah)?', NULL, false, false, NULL, false, false, 1.00, 61),
  ('audit_3_4', 'J', 62, 'Apakah kesejahteraan & keadilan seluruh pemangku kepentingan (karyawan, mitra, supplier, masyarakat) meningkat?', NULL, false, false, NULL, false, false, 1.00, 62),
  ('audit_3_4', 'J', 63, 'Apakah ada kewaspadaan & penjagaan terhadap hasad, fitnah internal & pengkhianatan "orang dekat"?', 'Khas muncul di fase keberhasilan besar (materi Sirah Anda).', false, false, NULL, false, false, 1.00, 63),
  ('audit_4_5', 'A', 1, 'Apakah lapisan persetujuan/birokrasi yang TIDAK menambah nilai sudah dipangkas? (uji: berapa approval untuk satu keputusan rutin?)', 'Birokrasi = sampah (muda) yang menumpuk dari fase Koordinasi. Hitung & potong.', true, false, NULL, false, false, 1.00, 1),
  ('audit_4_5', 'A', 2, 'Apakah wewenang keputusan didorong ke titik TERDEKAT dengan nilai (tim/unit diberdayakan), bukan menumpuk di kantor pusat?', 'Pergeseran "kontrol terpusat" → "kolaborasi terdistribusi" (Greiner).', true, false, NULL, false, false, 1.00, 2),
  ('audit_4_5', 'A', 3, 'Apakah laporan/form/rapat yang tidak dipakai untuk keputusan sudah dihentikan?', 'Jika tak ada yang membaca atau memutuskan darinya, ia beban.', false, false, NULL, false, false, 1.00, 3),
  ('audit_4_5', 'A', 4, 'Apakah struktur diratakan di mana lapisan tidak menambah nilai (kurangi overhead pusat)?', NULL, false, false, NULL, false, false, 1.00, 4),
  ('audit_4_5', 'A', 5, 'Apakah sistem kontrol bergeser dari "kontrol penuh" ke "berbasis pengecualian & kepercayaan" (real-time, exception-based)?', 'Kecerdasan sistem TETAP; bebannya yang dibuang.', false, false, NULL, false, false, 1.00, 5),
  ('audit_4_5', 'A', 6, 'Apakah setiap proses dibenarkan oleh nilai yang diberi ke pelanggan — jika tidak, dihentikan (value stream)?', NULL, false, false, NULL, false, false, 1.00, 6),
  ('audit_4_5', 'A', 7, 'Apakah ada unit kecil otonom (tim "dua-pizza") untuk menjalankan inisiatif/usaha baru dengan cepat?', 'Mengembalikan kelincahan tanpa kehilangan tulang punggung data.', false, false, NULL, false, false, 1.00, 7),
  ('audit_4_5', 'B', 8, 'Apakah ada MODEL bisnis terbukti & REPLICABLE (playbook operasi) yang bisa digandakan ke cabang/mitra baru?', 'Tanpa playbook, ekspansi = mengulang kerumitan dari nol di tiap tempat.', true, false, NULL, false, false, 1.00, 8),
  ('audit_4_5', 'B', 9, 'Apakah cabang/unit "paling sehat" sudah diidentifikasi sebagai model untuk direplikasi?', 'Materi Anda: cabang/franchise paling sehat jadi acuan.', false, false, NULL, false, false, 1.00, 9),
  ('audit_4_5', 'B', 10, 'Apakah standar mutu & brand experience terjaga seragam saat menggandakan, namun cukup fleksibel untuk lokal?', NULL, false, false, NULL, false, false, 1.00, 10),
  ('audit_4_5', 'B', 11, 'Apakah rantai pasok & kapasitas siap menopang lonjakan volume ekspansi?', NULL, false, false, NULL, false, false, 1.00, 11),
  ('audit_4_5', 'C', 12, 'Apakah ekspansi dibiayai dari posisi keuangan yang TAHAN BANTING — bukan dipaksakan saat rapuh?', 'Banyak bisnis mati justru saat ekspansi karena melompat dari posisi lemah.', true, false, NULL, false, false, 1.00, 12),
  ('audit_4_5', 'C', 13, 'Apakah ada kapasitas pendanaan ekspansi (kas/akses modal/investor) yang sehat & terukur?', NULL, false, false, NULL, false, false, 1.00, 13),
  ('audit_4_5', 'C', 14, 'Apakah konsolidasi keuangan multi-entitas/cabang berjalan akurat & tepat waktu?', NULL, false, false, NULL, false, false, 1.00, 14),
  ('audit_4_5', 'C', 15, 'Apakah setiap unit/cabang baru punya target balik modal (payback) & dipantau ketat?', NULL, false, false, NULL, false, false, 1.00, 15),
  ('audit_4_5', 'C', 16, 'Apakah risiko keuangan ekspansi (overtrading, beban tetap baru) dimodelkan sebelum eksekusi?', 'Overtrading: tumbuh terlalu cepat hingga kehabisan kas.', false, false, NULL, false, false, 1.00, 16),
  ('audit_4_5', 'D', 17, 'Apakah due diligence pajak & hukum dilakukan SEBELUM akuisisi/aliansi/franchise?', 'Membeli/bermitra tanpa due diligence = mewarisi masalah tersembunyi.', true, false, NULL, false, false, 1.00, 17),
  ('audit_4_5', 'D', 18, 'Apakah struktur multi-entitas/holding & transaksi afiliasi punya dokumentasi transfer pricing memadai?', 'Dasar: PMK transfer pricing terbaru (mis. PMK 172/2023) — konfirmasi versi berlaku.', false, false, NULL, false, false, 1.00, 18),
  ('audit_4_5', 'D', 19, 'Apakah model waralaba/kemitraan punya legalitas sesuai (mis. STPW & perjanjian waralaba terdaftar)?', 'Konfirmasi PP waralaba yang berlaku ke ahli hukum.', false, false, NULL, false, false, 1.00, 19),
  ('audit_4_5', 'D', 20, 'Apakah aspek persaingan usaha (KPPU) dipertimbangkan bila pangsa/akuisisi menjadi besar?', 'Dasar: UU 5/1999. Notifikasi merger bila memenuhi ambang.', false, true, 'Bila pangsa/akuisisi menjadi besar', true, false, 1.00, 20),
  ('audit_4_5', 'D', 21, 'Apakah perpajakan tetap tersistem di Coretax untuk SELURUH entitas baru?', NULL, false, false, NULL, false, false, 1.00, 21),
  ('audit_4_5', 'D', 22, 'Apakah ketenagakerjaan (PKWT/SUSU/BPJS/pesangon) tetap patuh di setiap unit/cabang baru?', 'Konsistensi kepatuhan tak boleh kendur saat menggandakan.', false, false, NULL, false, false, 1.00, 22),
  ('audit_4_5', 'D', 23, 'Apakah ekspansi lintas daerah/negara mempertimbangkan UMK lokal & regulasi setempat?', 'UMK berbeda tiap daerah (mis. Bandung 2026 Rp4.737.678 vs Bekasi ~Rp6 jt).', false, false, NULL, false, false, 1.00, 23),
  ('audit_4_5', 'D', 24, 'Apakah perlindungan data pribadi (UU PDP) terjaga saat skala & kanal bertambah?', 'Dasar: UU 27/2022.', false, false, NULL, false, false, 1.00, 24),
  ('audit_4_5', 'E', 25, 'Apakah ada lapisan pemimpin yang mampu menjalankan unit secara OTONOM — bukan satu owner?', 'Ekspansi mustahil bila tiap unit menunggu owner.', true, false, NULL, false, false, 1.00, 25),
  ('audit_4_5', 'E', 26, 'Apakah suksesi kepemimpinan (TERMASUK peran owner) bersih, teruji & direncanakan?', 'Estafet kepemimpinan (materi Sirah Anda). Kelangsungan melampaui pendiri.', true, false, NULL, false, false, 1.00, 26),
  ('audit_4_5', 'E', 27, 'Apakah kaderisasi menghasilkan pemimpin baru LEBIH CEPAT dari laju ekspansi?', 'Kalau pemimpin lebih lambat lahir dari cabang, mutu jatuh.', false, false, NULL, false, false, 1.00, 27),
  ('audit_4_5', 'E', 28, 'Apakah kepemimpinan berbasis kepercayaan & nilai, bukan kontrol & kehadiran fisik owner?', 'Materi Anda: sahabat ahli surga tak harus selalu bareng — kepemimpinan terdistribusi yang dipercaya.', false, false, NULL, false, false, 1.00, 28),
  ('audit_4_5', 'E', 29, 'Apakah ada mekanisme menjaga kualitas pemimpin yang dipromosikan/direkrut saat tumbuh cepat?', NULL, false, false, NULL, false, false, 1.00, 29),
  ('audit_4_5', 'F', 30, 'Apakah jalur ekspansi dipilih secara sadar (organik / franchise / kemitraan / akuisisi / jaringan)?', 'Bukan tumbuh asal tumbuh.', false, false, NULL, false, false, 1.00, 30),
  ('audit_4_5', 'F', 31, 'Apakah pemilihan mitra menilai kecocokan BUDAYA & NILAI — bukan hanya angka?', 'Mitra yang nilainya beda akan menggerus identitas Anda dari dalam.', false, false, NULL, false, false, 1.00, 31),
  ('audit_4_5', 'F', 32, 'Apakah ada playbook integrasi pasca-akuisisi / onboarding mitra baru?', NULL, false, false, NULL, false, false, 1.00, 32),
  ('audit_4_5', 'F', 33, 'Apakah ekspansi diuji bertahap (pilot) sebelum di-scale besar?', NULL, false, false, NULL, false, false, 1.00, 33),
  ('audit_4_5', 'F', 34, 'Apakah ketergantungan pada satu mitra/kanal/pelanggan besar dikelola (risiko konsentrasi)?', NULL, false, false, NULL, false, false, 1.00, 34),
  ('audit_4_5', 'G', 35, 'Apakah identitas & nilai inti ("dua warisan utama" Anda) terdefinisi tertulis & dijaga — tidak tergerus saat ekspansi?', 'QS 21:35 / slide Anda: sistem tetap tegak SEPANJANG dua warisan dijaga.', true, false, NULL, false, false, 1.00, 35),
  ('audit_4_5', 'G', 36, 'Apakah ada mekanisme transmisi budaya & nilai ke SETIAP unit/mitra baru?', 'Nilai tak menular sendiri; harus sengaja ditularkan.', false, false, NULL, false, false, 1.00, 36),
  ('audit_4_5', 'G', 37, 'Apakah misi/maksud (purpose) tetap menjadi penyaring keputusan ekspansi — bukan tumbuh demi tumbuh?', NULL, false, false, NULL, false, false, 1.00, 37),
  ('audit_4_5', 'G', 38, 'Apakah ada penjagaan agar mutu & akhlak layanan tidak turun saat menggandakan?', NULL, false, false, NULL, false, false, 1.00, 38),
  ('audit_4_5', 'G', 39, 'Apakah dilusi nilai / "musuh dalam selimut" / pengkhianatan dipantau sebagai risiko nyata?', 'Materi Sirah Anda: di puncak, gangguan justru datang dari dalam.', false, false, NULL, false, false, 1.00, 39),
  ('audit_4_5', 'H', 40, 'Apakah sistem memberi data real-time ke unit otonom agar mereka bisa memutuskan sendiri (bukan menunggu pusat)?', NULL, false, false, NULL, false, false, 1.00, 40),
  ('audit_4_5', 'H', 41, 'Apakah ada visibilitas konsolidasi untuk owner/board TANPA harus mikro-mengontrol unit?', NULL, false, false, NULL, false, false, 1.00, 41),
  ('audit_4_5', 'H', 42, 'Apakah keamanan & tata kelola data terjaga saat entitas/kanal bertambah?', NULL, false, false, NULL, false, false, 1.00, 42),
  ('audit_4_5', 'I', 43, 'Apakah skala besar TIDAK menggerus akhlak, ibadah, zuhud & integritas — bahkan menjadikannya makin baik?', 'Indikator scaling-up berhasil (materi Anda): trilyuner pun tetap dermawan & zuhud.', true, false, NULL, false, false, 1.00, 43),
  ('audit_4_5', 'I', 44, 'Apakah struktur ekspansi (akad, pembiayaan, kemitraan) dipastikan syariah oleh dewan/penasihat syariah?', NULL, false, false, NULL, false, false, 1.00, 44),
  ('audit_4_5', 'I', 45, 'Apakah keberkahan & manfaat bagi banyak pihak (karyawan, mitra, umat) menjadi ukuran — bukan hanya finansial?', NULL, false, false, NULL, false, false, 1.00, 45),
  ('audit_4_5', 'I', 46, 'Apakah ada kewaspadaan terhadap hasad, fitnah & pengkhianatan yang justru meningkat di puncak keberhasilan?', 'Materi Sirah Anda (QS 21:35): ujian terberat sering di puncak.', false, false, NULL, false, false, 1.00, 46)
) AS v(audit_code, section_code, question_number, question_text, guidance_text, is_key, is_conditional, condition_text, has_not_applicable, is_added, weight, sort_order)
JOIN audit_transitions a ON a.code = v.audit_code
JOIN test_sections s ON s.audit_transition_id = a.id AND s.code = v.section_code
ON CONFLICT (audit_transition_id, question_number) DO UPDATE SET
  section_id = EXCLUDED.section_id, question_text = EXCLUDED.question_text, guidance_text = EXCLUDED.guidance_text,
  is_key = EXCLUDED.is_key, is_conditional = EXCLUDED.is_conditional, condition_text = EXCLUDED.condition_text,
  has_not_applicable = EXCLUDED.has_not_applicable, is_added = EXCLUDED.is_added, weight = EXCLUDED.weight,
  sort_order = EXCLUDED.sort_order, is_active = true;

