-- Sections not present in xlsx are left as-is but reported by the checks below (none expected).

-- 6. Recompute audit_transitions totals from active rows
UPDATE audit_transitions a SET
  total_questions     = c.n,
  total_key_questions = c.k
FROM (SELECT audit_transition_id, count(*)::smallint AS n, count(*) FILTER (WHERE is_key)::smallint AS k
      FROM test_questions WHERE is_active GROUP BY audit_transition_id) c
WHERE c.audit_transition_id = a.id;

-- 7. Post-conditions (abort + rollback on any mismatch)
DO $$
DECLARE r record;
BEGIN
  FOR r IN
    WITH exp AS (SELECT 'audit_1_2' AS code, 92 AS n, 13 AS k, 8 AS s UNION ALL SELECT 'audit_2_3' AS code, 161 AS n, 18 AS k, 9 AS s UNION ALL SELECT 'audit_3_4' AS code, 63 AS n, 16 AS k, 10 AS s UNION ALL SELECT 'audit_4_5' AS code, 46 AS n, 9 AS k, 9 AS s)
    SELECT e.code, e.n, e.k, e.s,
      (SELECT count(*) FROM test_questions tq WHERE tq.audit_transition_id = a.id AND tq.is_active) AS got_n,
      (SELECT count(*) FROM test_questions tq WHERE tq.audit_transition_id = a.id AND tq.is_active AND tq.is_key) AS got_k,
      (SELECT count(*) FROM test_sections ts WHERE ts.audit_transition_id = a.id) AS got_s,
      (SELECT count(*) FROM test_questions tq JOIN test_sections ts ON ts.id = tq.section_id
        WHERE tq.audit_transition_id = a.id AND ts.audit_transition_id <> a.id) AS cross_links
    FROM exp e LEFT JOIN audit_transitions a ON a.code = e.code
  LOOP
    IF r.got_n <> r.n OR r.got_k <> r.k OR r.got_s <> r.s OR r.cross_links <> 0 THEN
      RAISE EXCEPTION 'Seed check failed for %: questions %/% key %/% sections %/% cross-links %',
        r.code, r.got_n, r.n, r.got_k, r.k, r.got_s, r.s, r.cross_links;
    END IF;
  END LOOP;
END $$;

-- 8. Sequence reset (ERD Catatan Implementasi §1; COALESCE-safe for empty tables)
SELECT setval('phases_id_seq', COALESCE((SELECT MAX(id) FROM phases), 1), (SELECT MAX(id) FROM phases) IS NOT NULL);
SELECT setval('audit_transitions_id_seq', COALESCE((SELECT MAX(id) FROM audit_transitions), 1), (SELECT MAX(id) FROM audit_transitions) IS NOT NULL);
SELECT setval('test_sections_id_seq', COALESCE((SELECT MAX(id) FROM test_sections), 1), (SELECT MAX(id) FROM test_sections) IS NOT NULL);
SELECT setval('test_questions_id_seq', COALESCE((SELECT MAX(id) FROM test_questions), 1), (SELECT MAX(id) FROM test_questions) IS NOT NULL);

COMMIT;
